mapper.select:
select a.target_id as targetId, a.user_id as id, u.nickname, u.avatar
from attitudes a join users u on a.user_id = u.id
where a.target_type = #{targetType}
  and a.target_id in
#{tid}
order by a.created_at desc

select count(*)
from attitudes
where target_type = #{targetType}
  and target_id = #{targetId}

mapper.update:
update notification_like
set like_count = like_count - 1,
    last_like_time = NOW()
where receiver_id = #{receiverId}
  and target_type = #{targetType}
  and target_id = #{targetId}

mapper.delete:
delete from notification_like
where receiver_id = #{receiverId}
  and target_type = #{targetType}
  and target_id = #{targetId}
  and like_count <= 0
